; otir.asm -- chapter 20: WHERE IT BREAKS: a page copied with OTIR while the paper is drawn
; generated by gen20.py
        INCLUDE "msx.inc"
        OUTPUT "otir.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
BOX_EMPTY EQU 1             ; the library's two boxes, characters 1 and 2
BOX_FULL  EQU 2
; A page of 768 names copied to the name table in the paper's lines, from its
; first line, with OTIR, 23 T-states a byte.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E0          ; display on, and the frame's signal on
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; the frame's interrupt
        di
        ld a, ($002B)           ; 14: bit 7 is 1 on a 50 Hz machine
        rla                     ;  5
        jp nc, wj         ; 11
w5s:    ld de, 911
w5:     dec de
        ld a, d
        or e
        jr nz, w5
        ld c, 0
        ld c, 0
        ld c, 0
        ld c, 0
        nop
        nop
        nop
        nop
        jp wg             ; 11
wj:
w6s:    ld de, 525
w6:     dec de
        ld a, d
        or e
        jr nz, w6
        nop
        nop
        nop
wg:
s1:     ld hl, page             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $1800        ; 40
        ld b, 0                 ;  8: 256
        ld d, 3                 ;  8: three times 256
x1:     otir                    ; 21 + 2: 23 a byte, 18 the last
        dec d                   ;  5
        jp nz, x1               ; 11
z1:
done:   jr done

; isr: the frame's interrupt, taken once, to start in step with the picture
isr:    push af
        in a, (VDP_CTRL)        ; the status: the VDP takes its signal down
        pop af
        ei
        ret
page:
        db "00 THE VDP TAKES A BYTE WHEN IT "
        db "01 THE VDP TAKES A BYTE WHEN IT "
        db "02 THE VDP TAKES A BYTE WHEN IT "
        db "03 THE VDP TAKES A BYTE WHEN IT "
        db "04 THE VDP TAKES A BYTE WHEN IT "
        db "05 THE VDP TAKES A BYTE WHEN IT "
        db "06 THE VDP TAKES A BYTE WHEN IT "
        db "07 THE VDP TAKES A BYTE WHEN IT "
        db "08 THE VDP TAKES A BYTE WHEN IT "
        db "09 THE VDP TAKES A BYTE WHEN IT "
        db "10 THE VDP TAKES A BYTE WHEN IT "
        db "11 THE VDP TAKES A BYTE WHEN IT "
        db "12 THE VDP TAKES A BYTE WHEN IT "
        db "13 THE VDP TAKES A BYTE WHEN IT "
        db "14 THE VDP TAKES A BYTE WHEN IT "
        db "15 THE VDP TAKES A BYTE WHEN IT "
        db "16 THE VDP TAKES A BYTE WHEN IT "
        db "17 THE VDP TAKES A BYTE WHEN IT "
        db "18 THE VDP TAKES A BYTE WHEN IT "
        db "19 THE VDP TAKES A BYTE WHEN IT "
        db "20 THE VDP TAKES A BYTE WHEN IT "
        db "21 THE VDP TAKES A BYTE WHEN IT "
        db "22 THE VDP TAKES A BYTE WHEN IT "
        db "23 THE VDP TAKES A BYTE WHEN IT "

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
